import{_ as i,a0 as l,w as p,s as r,I as s,x as t,a1 as o,A as e,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"理解 Linux 中的 Shutdown、Poweroff、Halt 和 Reboot 命令 | LCTT x X-CMD","titleTemplate":false,"description":"理解 Linux 中的 Shutdown、Poweroff、Halt 和 Reboot 命令 | LCTT (201706) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"理解 Linux 中的 Shutdown、Poweroff、Halt 和 Reboot 命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"理解 Linux 中的 Shutdown、Poweroff、Halt 和 Reboot 命令 | LCTT (201706) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201706/20170512 Understanding Shutdown, Poweroff Halt and Reboot Commands in Linux","title":"理解 Linux 中的 Shutdown、Poweroff、Halt 和 Reboot 命令","tag":"201706","desc":""},"relativePath":"201706/20170512 Understanding Shutdown, Poweroff Halt and Reboot Commands in Linux.md","filePath":"[post].md"}'),h={name:"201706/20170512 Understanding Shutdown, Poweroff Halt and Reboot Commands in Linux.md"};function u(f,n,b,g,w,m){const a=l("Link");return p(),r("div",null,[n[16]||(n[16]=s("h1",{id:"理解-linux-中的-shutdown、poweroff、halt-和-reboot-命令",tabindex:"-1"},[t("理解 Linux 中的 Shutdown、Poweroff、Halt 和 Reboot 命令 "),s("a",{class:"header-anchor",href:"#理解-linux-中的-shutdown、poweroff、halt-和-reboot-命令","aria-label":"Permalink to “理解 Linux 中的 Shutdown、Poweroff、Halt 和 Reboot 命令”"},"​")],-1)),n[17]||(n[17]=s("p",null,[t("在本篇中，我们会向你解释 "),s("strong",null,"shutdown、poweroff、halt 以及 reboot"),t(" 命令。我们会解释当使用可选项时，它们实际做了什么。")],-1)),s("p",null,[n[1]||(n[1]=t("如果你想深入管理 Linux 服务器，那么为了有效和可靠的服务器管理，这些",-1)),o(a,{href:"https://www.tecmint.com/60-commands-of-linux-a-guide-from-newbies-to-system-administrator/"},{default:e(()=>[...n[0]||(n[0]=[t("重要的 Linux 命令",-1)])]),_:1}),n[2]||(n[2]=t("你需要完全理解。",-1))]),n[18]||(n[18]=d(`<p>通常上，当你想要关闭或者重启你的机器时，你会运行下面之一的命令：</p><h3 id="shutdown-命令" tabindex="-1">Shutdown 命令 <a class="header-anchor" href="#shutdown-命令" aria-label="Permalink to “Shutdown 命令”">​</a></h3><p><strong>shutdown</strong> 会给系统计划一个时间关机。它可被用于停止、关机、重启机器。</p><p>你也许会指定一个时间字符串（通常是 “now” 或者 “hh:mm” 用于小时/分钟）作为第一个参数。额外地，你也可以设置一个广播信息在系统关闭前发送给所有已登录的用户。</p><p>重要：如果使用了时间参数，系统关机前 5 分钟，/run/nologin 文件会被创建来确保没有人可以再登录。</p><p>shutdown 命令示例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># shutdown</span></span>
<span class="line"><span># shutdown now</span></span>
<span class="line"><span># shutdown 13:20  </span></span>
<span class="line"><span># shutdown -p now	#关闭机器</span></span>
<span class="line"><span># shutdown -H now	#停止机器		</span></span>
<span class="line"><span># shutdown -r09:35	#在 09:35am 重启机器</span></span></code></pre></div><p>要取消即将的关机，只要输入下面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># shutdown -c</span></span></code></pre></div><h3 id="halt-命令" tabindex="-1">Halt 命令 <a class="header-anchor" href="#halt-命令" aria-label="Permalink to “Halt 命令”">​</a></h3><p><strong>halt</strong> 通知硬件来停止所有的 CPU 功能，但是仍然保持通电。你可以用它使系统处于低层维护状态。</p><p>注意在有些情况会它会完全关闭系统。下面是 halt 命令示例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># halt		   #停止机器</span></span>
<span class="line"><span># halt -p	   #关闭机器</span></span>
<span class="line"><span># halt --reboot    #重启机器</span></span></code></pre></div><h3 id="poweroff-命令" tabindex="-1">poweroff 命令 <a class="header-anchor" href="#poweroff-命令" aria-label="Permalink to “poweroff 命令”">​</a></h3><p><strong>poweroff</strong> 会发送一个 ACPI 信号来通知系统关机。</p><p>下面是 poweroff 命令示例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># poweroff   	       #关闭机器</span></span>
<span class="line"><span># poweroff --halt      #停止机器</span></span>
<span class="line"><span># poweroff --reboot    #重启机器</span></span></code></pre></div><h3 id="reboot-命令" tabindex="-1">Reboot 命令 <a class="header-anchor" href="#reboot-命令" aria-label="Permalink to “Reboot 命令”">​</a></h3><p>reboot 通知系统重启。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># reboot            #重启机器</span></span>
<span class="line"><span># reboot --halt     #停止机器</span></span>
<span class="line"><span># reboot -p   	    #关闭机器</span></span></code></pre></div><p>就是这样了！如先前提到的，理解这些命令能够有效并可靠地在多用户环境下管理 Linux 服务器。你有一些额外的想法么？在评论区留言与我们分享。</p><hr><p>作者简介：</p><p>Aaron Kili 是一名 Linux 和 F.O.S.S 的爱好者，未来的 Linux 系统管理员、网站开发人员，目前是 TecMint 的内容创作者，他喜欢用电脑工作，并乐于分享知识。</p><hr>`,25)),s("p",null,[n[4]||(n[4]=t("via: ",-1)),o(a,{href:"https://www.tecmint.com/shutdown-poweroff-halt-and-reboot-commands-in-linux/"},{default:e(()=>[...n[3]||(n[3]=[t("https://www.tecmint.com/shutdown-poweroff-halt-and-reboot-commands-in-linux/",-1)])]),_:1})]),s("p",null,[n[8]||(n[8]=t("作者：",-1)),o(a,{href:"https://www.tecmint.com/author/aaronkili/"},{default:e(()=>[...n[5]||(n[5]=[t("Aaron Kili ",-1)])]),_:1}),n[9]||(n[9]=t(" 译者：",-1)),o(a,{href:"https://github.com/geekpi"},{default:e(()=>[...n[6]||(n[6]=[t("geekpi",-1)])]),_:1}),n[10]||(n[10]=t(" 校对：",-1)),o(a,{href:"https://github.com/jasminepeng"},{default:e(()=>[...n[7]||(n[7]=[t("jasminepeng",-1)])]),_:1})]),s("p",null,[n[13]||(n[13]=t("本文由 ",-1)),o(a,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...n[11]||(n[11]=[t("LCTT",-1)])]),_:1}),n[14]||(n[14]=t(" 原创编译，",-1)),o(a,{href:"https://linux.cn/"},{default:e(()=>[...n[12]||(n[12]=[t("Linux中国",-1)])]),_:1}),n[15]||(n[15]=t(" 荣誉推出",-1))])])}const c=i(h,[["render",u]]);export{C as __pageData,c as default};
